import {ingredients,recipes} from './data.js';
import {pantryFor} from './pantry.js';
const $=s=>document.querySelector(s), byId=Object.fromEntries(ingredients.map(i=>[i.id,i]));
const read=(key,fallback)=>{try{const value=JSON.parse(localStorage.getItem(key));return Array.isArray(value)?value:fallback}catch{return fallback}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}};
const selected=new Set(read('gusto-ingredients',[]).filter(id=>byId[id]));
let cart=read('gusto-cart',[]).filter(x=>recipes.some(r=>r.id===x.id)&&Number.isInteger(x.servings)&&x.servings>0&&x.servings<=6);
let checked=new Set(read('gusto-checked',[])),group='Todos',suggested=false,expanded=false,activeRecipe=null,servings=1;
const groups=['Todos',...new Set(ingredients.map(i=>i.group))];
const fmt=n=>new Intl.NumberFormat('es-ES',{maximumFractionDigits:2}).format(n);
const quantity=(item,n=1)=>`${fmt(item.qty*n)} ${item.unit}`;
const name=id=>byId[id]?.name||id;
const persist=()=>{write('gusto-cart',cart);write('gusto-checked',[...checked]);$('#cart-count').textContent=cart.length};
const notify=msg=>{$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2500)};
function drawGroups(){$('#groups').innerHTML=groups.map(g=>`<button type="button" class="${group===g?'active':''}" aria-pressed="${group===g}" data-group="${g}">${g}</button>`).join('')}
function drawIngredients(){const q=$('#ingredient-search').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const list=ingredients.filter(i=>(group==='Todos'||i.group===group)&&i.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));$('#ingredients').innerHTML=list.length?list.map(i=>`<button class="ingredient ${selected.has(i.id)?'selected':''}" data-ingredient="${i.id}" aria-pressed="${selected.has(i.id)}"><span class="tick" aria-hidden="true">${selected.has(i.id)?'✓':''}</span><img src="assets/ingredient-${i.id}.svg" alt="" loading="lazy"><span class="ingredient-name">${i.name}</span></button>`).join(''):'<p>No hay ingredientes con ese nombre.</p>';$('#selection-count').textContent=`${selected.size} ingrediente${selected.size===1?'':'s'} elegido${selected.size===1?'':'s'}`;$('#selection-summary').textContent=selected.size?[...selected].map(name).join(' · '):'Una buena receta empieza con tus favoritos.';write('gusto-ingredients',[...selected])}
export function affinity(r,selection=selected){return r.items.filter(i=>selection.has(i.id)).length}
function ordered(){return [...recipes].sort((a,b)=>$('#sort').value==='time'?a.time-b.time||affinity(b)-affinity(a):affinity(b)-affinity(a)||affinity(b)/b.items.length-affinity(a)/a.items.length)}
function drawRecipes(){const all=ordered(),list=all.slice(0,expanded?recipes.length:20);$('#results-title').textContent=suggested?'Tus recetas, a tu gusto':'Un poco de inspiración';$('#results-description').textContent=suggested?`${list.length} propuestas ordenadas ${$('#sort').value==='time'?'por tiempo de preparación':'por coincidencias con tus favoritos'}.`:`${recipes.length} recetas sencillas, con el estilo de tus guías de alimentación.`;const note=$('#result-note');note.hidden=!suggested;note.textContent=selected.size?'Tus favoritos sirven para ordenar las propuestas. Las recetas pueden llevar otros ingredientes: revisa la lista completa en cada ficha. Las opciones sin coincidencias aparecen como ideas para explorar.':'No has marcado ingredientes: te mostramos 20 ideas del recetario para empezar.';$('#recipe-grid').innerHTML=list.map((r,i)=>{const hits=affinity(r);return `<button class="recipe-card" data-recipe="${r.id}" aria-label="Ver receta: ${r.name}"><div class="recipe-picture" style="--tint:${['#e6e9d8','#efe8d9','#e8e7dc','#e3e9df'][i%4]}"><img src="assets/${r.id}.svg" alt="Ilustración de ${r.name.toLowerCase()}" loading="lazy"><span class="picture-badge">${r.kind}</span></div><h3>${r.name}</h3><div class="recipe-meta"><span>◷ ${r.time} min</span><span>1 ración</span><span>Ver receta ↗</span></div>${suggested&&selected.size?`<div class="match-label">${hits?`${hits} coincidencia${hits===1?'':'s'} · ${r.items.filter(x=>selected.has(x.id)).map(x=>name(x.id)).join(', ')}`:'Otra idea para explorar'}</div>`:''}</button>`}).join('');$('#show-all').hidden=expanded}
function openRecipe(id){activeRecipe=recipes.find(r=>r.id===id);servings=1;drawRecipe();$('#recipe-dialog').showModal()}
function drawRecipe(){const r=activeRecipe;$('#recipe-content').innerHTML=`<div class="modal-top"><p>RECETARIO · ${r.source}</p><button class="close" data-close aria-label="Cerrar receta">×</button></div><div class="detail-hero"><img src="assets/${r.id}.svg" alt="Ilustración de ${r.name.toLowerCase()}"><div><div class="eyebrow">SENCILLO Y A TU GUSTO</div><h2 id="recipe-title">${r.name}</h2><p>◷ ${r.time} minutos · ${r.kind} · Dificultad fácil</p></div></div><div class="detail-body"><section><h3>Lista de la compra</h3><div class="servings"><span>Raciones</span><button data-servings="-1" ${servings===1?'disabled':''} aria-label="Reducir raciones">−</button><strong>${servings}</strong><button data-servings="1" ${servings===6?'disabled':''} aria-label="Añadir ración">+</button></div><ul class="shopping-items">${r.items.map(i=>`<li><span>${name(i.id)}</span><strong style="margin-left:auto;white-space:nowrap;font-weight:500">${quantity(i,servings)}</strong></li>`).join('')}${pantryFor(r).map(label=>`<li><span>${label}</span><span style="margin-left:auto">Al gusto</span></li>`).join('')}</ul><p class="small-note">Los ingredientes marcados son preferencias; no se consideran alimentos que ya tengas en casa.</p></section><section><h3>Así se prepara</h3><ol class="detail-steps">${r.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="small-note">Origen: ${r.source}. Cantidades por ración y pasos adaptados de tus guías; los tiempos son orientativos. Se han completado cantidades que no estaban especificadas. La imagen es una ilustración.</p></section></div><div class="modal-actions"><button class="primary" id="add-cart">Añadir a mi compra <span>＋</span></button><button class="secondary" id="download-recipe">Descargar receta y lista ↓</button></div>`}
function addCart(){const exists=cart.find(x=>x.id===activeRecipe.id);if(exists){exists.servings=servings;notify('Raciones actualizadas en tu compra')}else{cart.push({id:activeRecipe.id,servings});notify('Receta añadida a tu lista de la compra')}checked.clear();persist()}
export function aggregate(entries){const result=new Map();for(const entry of entries){const r=recipes.find(x=>x.id===entry.id);for(const item of r.items){const key=`${item.id}|${item.unit}`;if(!result.has(key))result.set(key,{...item,qty:0});result.get(key).qty+=item.qty*entry.servings}}return [...result.values()].sort((a,b)=>name(a.id).localeCompare(name(b.id),'es'))}
const cartPantry=()=>[...new Set(cart.flatMap(c=>pantryFor(recipes.find(r=>r.id===c.id))))];
function cartText(){return 'MI LISTA DE LA COMPRA · A TU GUSTO\n\n'+cart.map(c=>`${recipes.find(r=>r.id===c.id).name} · ${c.servings} raciones`).join('\n')+'\n\nINGREDIENTES\n'+aggregate(cart).map(i=>`☐ ${name(i.id)}: ${quantity(i)}`).join('\n')+'\n'+cartPantry().map(label=>`☐ ${label}: al gusto`).join('\n')}
function drawCart(){const list=aggregate(cart);$('#cart-content').innerHTML=`<div class="modal-top"><p>UN POCO DE ORGANIZACIÓN, MUCHO MÁS FÁCIL</p><button class="close" data-close aria-label="Cerrar lista de la compra">×</button></div><div class="cart-body"><h2 id="cart-title">Tu lista de la compra</h2>${cart.length?`<p class="small-note">Las cantidades se suman entre recetas cuando usan la misma unidad. Marca lo que ya tengas o vayas comprando.</p>${cart.map(c=>{const r=recipes.find(r=>r.id===c.id);return `<div class="cart-recipe"><img src="assets/${r.id}.svg" alt=""><div>${r.name}</div><label><input type="number" min="1" max="6" value="${c.servings}" data-cart-servings="${c.id}" aria-label="Raciones de ${r.name}"> rac.</label><button data-remove="${r.id}" aria-label="Quitar ${r.name}">Quitar</button></div>`}).join('')}<h3>Lo que necesitas</h3><ul class="shopping-items cart-list">${[...list.map(i=>({key:`${i.id}|${i.unit}`,label:`${name(i.id)} · ${quantity(i)}`})),...cartPantry().map(label=>({key:`pantry:${label}`,label:`${label} · al gusto`}))].map(i=>`<li class="${checked.has(i.key)?'checked':''}"><label><input type="checkbox" data-check="${i.key}" ${checked.has(i.key)?'checked':''}> <span>${i.label}</span></label></li>`).join('')}</ul>`:'<div class="empty"><h3>Tu próxima comida empieza aquí.</h3><p>Abre una receta y pulsa «Añadir a mi compra» para reunir sus ingredientes.</p><button class="primary" data-close>Explorar recetas →</button></div>'}</div>${cart.length?'<div class="modal-actions"><button class="primary" id="download-cart">Descargar lista ↓</button><button class="secondary" id="copy-cart">Copiar lista</button><button class="text-button" id="clear-cart">Vaciar lista</button></div>':''}`}
function download(text,filename){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#groups').addEventListener('click',e=>{const b=e.target.closest('[data-group]');if(b){group=b.dataset.group;drawGroups();drawIngredients()}});
$('#ingredients').addEventListener('click',e=>{const b=e.target.closest('[data-ingredient]');if(!b)return;const id=b.dataset.ingredient;selected.has(id)?selected.delete(id):selected.add(id);drawIngredients();if(suggested)drawRecipes()});
$('#ingredient-search').addEventListener('input',drawIngredients);
$('#clear').addEventListener('click',()=>{selected.clear();drawIngredients();drawRecipes()});
$('#suggest').addEventListener('click',()=>{suggested=true;expanded=false;drawRecipes();$('#recetas').scrollIntoView({behavior:'smooth'})});
$('#sort').addEventListener('change',drawRecipes);
$('#show-all').addEventListener('click',()=>{expanded=true;drawRecipes()});
$('#recipe-grid').addEventListener('click',e=>{const b=e.target.closest('[data-recipe]');if(b)openRecipe(b.dataset.recipe)});
$('#recipe-dialog').addEventListener('click',e=>{if(e.target.closest('[data-close]'))$('#recipe-dialog').close();const b=e.target.closest('[data-servings]');if(b){servings=Math.max(1,Math.min(6,servings+Number(b.dataset.servings)));drawRecipe()}if(e.target.closest('#add-cart'))addCart();if(e.target.closest('#download-recipe')){const r=activeRecipe;download(`${r.name}\n${servings} raciones · ${r.time} minutos\nOrigen: ${r.source}\n\nINGREDIENTES\n${r.items.map(i=>`${name(i.id)}: ${quantity(i,servings)}`).join('\n')}\n${pantryFor(r).map(label=>`${label}: al gusto`).join('\n')}\n\nPREPARACIÓN\n${r.steps.map((s,i)=>`${i+1}. ${s}`).join('\n\n')}\n\nCantidades y pasos adaptados de las guías. Tiempos orientativos.`,`${r.id}.txt`)}});
$('#open-cart').addEventListener('click',()=>{drawCart();$('#cart-dialog').showModal()});
$('#cart-dialog').addEventListener('click',async e=>{if(e.target.closest('[data-close]'))$('#cart-dialog').close();const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(c=>c.id!==remove.dataset.remove);checked.clear();persist();drawCart()}if(e.target.closest('#download-cart'))download(cartText(),'mi-lista-de-la-compra.txt');if(e.target.closest('#clear-cart')){cart=[];checked.clear();persist();drawCart();notify('Lista vaciada')}if(e.target.closest('#copy-cart')){try{await navigator.clipboard.writeText(cartText());notify('Lista copiada')}catch{notify('No se pudo copiar. Puedes descargar la lista.')}}});
$('#cart-dialog').addEventListener('change',e=>{const b=e.target.closest('[data-check]');if(b){b.checked?checked.add(b.dataset.check):checked.delete(b.dataset.check);persist();b.closest('li').classList.toggle('checked',b.checked)}const s=e.target.closest('[data-cart-servings]');if(s){cart.find(c=>c.id===s.dataset.cartServings).servings=Math.max(1,Math.min(6,Math.round(Number(s.value)||1)));checked.clear();persist();drawCart()}});
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
document.addEventListener('gusto:recipe',e=>{if(recipes.some(r=>r.id===e.detail))openRecipe(e.detail)});
$('#show-all').textContent=`Explorar las ${recipes.length} recetas`;
drawGroups();drawIngredients();drawRecipes();persist();
